contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 amount, bool makeTargetFail) public payable {
        require(address(this).balance >= amount, "insufficient balance");
        uint256 beforeC = address(c).balance;
        bool reverted;
        if (makeTargetFail) {
            // Force the call to the fixed target to fail by using a small amount? 
            // Instead, we just call go and observe. To create a fail, we can require c to have insufficient balance? 
            // But that would not be a failed call to go itself. We need to make the external call fail.
            // Since target is a fixed address, we can't easily force failure. So we use the revert path when forwarding fails.
            // The rule we want: if go reverts, c balance unchanged.
            // We can make go revert by sending more than c has? But c's balance is separate from msg.value.
            // Actually value is sent from this contract, so c's balance doesn't matter for the transfer.
            // The target call succeeds if target accepts ether. If target rejects, go reverts and c keeps the ether.
            // We cannot control target, so we use the try/catch to detect revert.
            try c.go{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.go{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }
        uint256 afterC = address(c).balance;
        assert(reverted == false || afterC == beforeC);
    }
}

